using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
public class CastleLocalizedUI084
{
 static StringBuilder manifest=new StringBuilder();static int index;
 static string Path(Transform t){return t.parent==null?t.name:Path(t.parent)+"/"+t.name;}
 static void Record(GameObject g,string text){manifest.AppendLine(Path(g.transform)+"\t"+text.Replace("\n","\\n"));}
 static Transform Group(string n,Transform p){var t=new GameObject(n).transform;t.SetParent(p,false);return t;}
 static void Prop(string path,Transform parent,string name,Vector3 pos,Vector3 rot,float height){var src=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(src==null)throw new Exception("Missing decor "+path);var g=UnityEngine.Object.Instantiate(src,parent);g.name=name;g.transform.localPosition=pos;g.transform.localRotation=Quaternion.Euler(rot);foreach(var c in g.GetComponentsInChildren<Component>(true)){if(c==null)throw new Exception("Decor has missing script");if(c is Transform||c is MeshFilter||c is MeshRenderer||c is SkinnedMeshRenderer)continue;UnityEngine.Object.DestroyImmediate(c);}var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);g.transform.localScale*=height/b.size.y;b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);g.transform.position+=parent.TransformPoint(pos)-b.center;}
 public static string Main(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/CastleServicesWorkshop.unity"||scene.isDirty||EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Saved Edit Mode required");var root=GameObject.Find("Castle_Services_Prototype").transform;var h=root.Find("03_Service_Houses/04_Professions");if(h.Find("24_Armory_Wall_Decor")!=null)throw new Exception("Already applied");
 foreach(Transform rug in h.Find("23_Armory_Pickup_Mats")){foreach(Transform part in rug){if(part.name=="Service_Rug"){var s=part.localScale;s.z=1.05f;part.localScale=s;}else if(part.name=="Rug_Side_Trim"){var s=part.localScale;s.z=1.005f;part.localScale=s;}else if(part.name=="Rug_End_Trim"){var p=part.localPosition;p.z=Mathf.Sign(p.z)*.485f;part.localPosition=p;}}}
 h.Find("16_Run_Interior/EditorOnly_StockPreview").gameObject.SetActive(false);
 var points=h.Find("15_Gameplay_Source/StorePoints").Cast<Transform>().Where(t=>t.name.StartsWith("storePoint")).ToArray();for(int i=0;i<points.Length;i++){var p=points[i];var buy=p.GetComponentsInChildren<Transform>(true).First(t=>t.name=="buyPoint");float side=i<2?-1:1;float z=i%2==0?-1.15f:1.75f;buy.position=h.TransformPoint(new Vector3(side*1.02f,1.35f,z));buy.rotation=h.rotation;var marker=Group("PublicDropCenter",buy);marker.localPosition=Vector3.zero;PrefabUtility.RecordPrefabInstancePropertyModifications(buy);foreach(var tm in p.GetComponentsInChildren<Text>(true)){if(tm.name=="itemName"){tm.text="";tm.resizeTextForBestFit=true;tm.resizeTextMinSize=10;tm.resizeTextMaxSize=24;tm.horizontalOverflow=HorizontalWrapMode.Wrap;PrefabUtility.RecordPrefabInstancePropertyModifications(tm);}}var can=p.Find("Canvas");can.localPosition=new Vector3(0,.6f,-.47f);can.localScale=Vector3.one*.006f;PrefabUtility.RecordPrefabInstancePropertyModifications(can);var price=p.Find("priceCanvas");price.localPosition=new Vector3(0,1.04f,-.47f);price.localScale=Vector3.one*.008f;PrefabUtility.RecordPrefabInstancePropertyModifications(price);}
 var decor=Group("24_Armory_Wall_Decor",h);Prop("Assets/Import/3D Cartoon Village/Prefabs/Shield.prefab",decor,"Rear_Wall_Shield",new Vector3(0,2.8f,3.45f),new Vector3(0,180,0),1.0f);Prop("Assets/Import/Kenney Assets/Pirate Kit/Models/FBX format/sword.fbx",decor,"Crossed_Sword_Left",new Vector3(-.65f,2.8f,3.35f),new Vector3(0,0,35),1.15f);Prop("Assets/Import/Kenney Assets/Pirate Kit/Models/FBX format/sword.fbx",decor,"Crossed_Sword_Right",new Vector3(.65f,2.8f,3.35f),new Vector3(0,0,-35),1.15f);Prop("Assets/Import/3D Cartoon Village/Prefabs/Shield2.prefab",decor,"Left_Wall_Shield",new Vector3(-2.64f,2.8f,.3f),new Vector3(0,90,0),.8f);Prop("Assets/Import/3D Cartoon Village/Prefabs/Shield2.prefab",decor,"Right_Wall_Shield",new Vector3(2.64f,2.8f,.3f),new Vector3(0,-90,0),.8f);
 var meshes=root.GetComponentsInChildren<TextMesh>(true);int removed=0,converted=0;foreach(var tm in meshes){var t=tm.transform;var r=tm.GetComponent<MeshRenderer>();bool remove=t.name=="Product_Label"||(t.IsChildOf(h)&&t.name=="Pickup_Label");if(!remove){var b=r.localBounds;var go=new GameObject("Localized_UI_"+(++index),typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler));go.transform.SetParent(t,false);go.transform.localPosition=b.center;go.transform.localScale=Vector3.one*.01f;var canvas=go.GetComponent<Canvas>();canvas.renderMode=RenderMode.WorldSpace;var rect=go.GetComponent<RectTransform>();rect.sizeDelta=new Vector2(Mathf.Max(.5f,b.size.x+.12f)*100,Mathf.Max(.22f,b.size.y+.12f)*100);var scaler=go.GetComponent<CanvasScaler>();scaler.dynamicPixelsPerUnit=20;var textGO=new GameObject("Localized_Text",typeof(RectTransform),typeof(Text));textGO.transform.SetParent(go.transform,false);var tr=textGO.GetComponent<RectTransform>();tr.anchorMin=Vector2.zero;tr.anchorMax=Vector2.one;tr.offsetMin=tr.offsetMax=Vector2.zero;var ui=textGO.GetComponent<Text>();ui.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");ui.fontSize=48;ui.resizeTextForBestFit=true;ui.resizeTextMinSize=10;ui.resizeTextMaxSize=64;ui.alignment=TextAnchor.MiddleCenter;ui.color=tm.color;ui.text=tm.text;ui.raycastTarget=false;ui.horizontalOverflow=HorizontalWrapMode.Wrap;ui.verticalOverflow=VerticalWrapMode.Truncate;Record(textGO,tm.text);converted++;}else{t.gameObject.SetActive(false);removed++;}UnityEngine.Object.DestroyImmediate(tm);UnityEngine.Object.DestroyImmediate(r);}
 // Native shop UI already binds itemName and prices through StorePoint. Only static titles need new localization keys.
 foreach(var ui in root.GetComponentsInChildren<Text>(true)){if(ui.name=="Localized_Text"||ui.name=="itemName"||ui.name=="price"||string.IsNullOrWhiteSpace(ui.text)||ui.text=="E")continue;if(ui.text=="Gun Store"||ui.text=="Store"||ui.text=="Shop"||ui.text=="Sell"||ui.text=="Купить"||ui.text=="Не хватает денег")Record(ui.gameObject,ui.text);}
 File.WriteAllText("Temp/castle-ui084.tsv",manifest.ToString());AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Docs/assets/examples/CASTLE_UI084_VALIDATION.txt","Converted "+converted+" TextMesh labels to World Space Canvas/UI Text; removed "+removed+" fixed product/pickup labels; 4 identical 1.15x1.05 mats; 5 decorative assets without colliders/scripts; native StorePoint itemName references retained.\n");return "Converted="+converted+" removed="+removed+"; localization manifest saved.";}
}
